/**
 * Sign in with Apple in a browser, and the nonce every Apple sign-in carries.
 *
 * The nonce binds an identity token to the sign-in that asked for it. A
 * random value is made here and only its SHA-256 goes to Apple, which copies
 * it into the token; the raw value goes to the API with the token, and the
 * API refuses a token whose nonce is not its hash. Anyone who sees a token on
 * its way sees only the hash, so the token cannot be replayed. The iPhone
 * app's system sheet follows the same convention.
 */

/**
 * What one Apple sign-in hands over: the identity token, the name Apple
 * shares the first time only, and the authorization code that came with
 * the token (with the redirect it is bound to on the web). The API trades
 * the code for a refresh token it keeps only so it can revoke it when the
 * account is deleted, as Apple asks; signing in never depends on it.
 */
export interface AppleCredentialFromApple {
  idToken: string;
  displayName: string | undefined;
  code?: string;
  redirectUri?: string;
}

/** A fresh nonce: the raw value for the API and its hash for Apple. */
export interface AppleNonce {
  raw: string;
  hashed: string;
}

/** 32 random bytes: far more than enough to be unguessable. */
const NONCE_BYTES = 32;

function hex(bytes: Uint8Array): string {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
}

export async function makeAppleNonce(): Promise<AppleNonce> {
  const raw = hex(crypto.getRandomValues(new Uint8Array(NONCE_BYTES)));
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(raw));
  return { raw, hashed: hex(new Uint8Array(digest)) };
}

/** What Apple's JavaScript SDK puts on the window once loaded. */
interface AppleSdk {
  auth: {
    init: (config: {
      clientId: string;
      scope: string;
      redirectURI: string;
      state: string;
      nonce: string;
      usePopup: boolean;
    }) => void;
    signIn: () => Promise<{
      authorization: { id_token: string; code: string; state?: string };
      user?: { name?: { firstName?: string; lastName?: string } };
    }>;
  };
}

/** Apple's SDK, pinned to the documented URL; the CSP names its host. */
const APPLE_SDK_URL = 'https://appleid.cdn-apple.com/appleauth/static/jsapi/appleid/1/en_US/appleid.auth.js';

/**
 * Runs Apple's popup sign-in, which answers the page directly (no server
 * callback). `state` is checked on the way back, so an answer meant for
 * another attempt is never used.
 *
 * Browsers open a popup only in direct answer to a tap, and Safari forgets
 * the tap at the first wait. So when the SDK is already loaded (see
 * preloadAppleSdk) nothing here waits before the popup opens; only a first
 * tap before the script arrived has to wait for it.
 */
export async function appleWebSignIn(
  clientId: string,
  redirectUri: string,
  hashedNonce: string,
): Promise<AppleCredentialFromApple> {
  const sdk = loadedSdk() ?? (await loadAppleSdk());
  const state = hex(crypto.getRandomValues(new Uint8Array(16)));
  sdk.auth.init({
    clientId,
    scope: 'name email',
    redirectURI: redirectUri,
    state,
    nonce: hashedNonce,
    usePopup: true,
  });
  const result = await sdk.auth.signIn();
  if (result.authorization.state !== state) throw new Error('Apple answered for another sign-in');
  const idToken = result.authorization.id_token;
  if (!idToken) throw new Error('Apple returned no identity token');
  const name = result.user?.name;
  const displayName = [name?.firstName, name?.lastName].filter(Boolean).join(' ').trim();
  const code = result.authorization.code;
  return {
    idToken,
    displayName: displayName === '' ? undefined : displayName,
    // The code is bound to the redirect the popup named, so the API needs
    // both to trade it (for a token it keeps only to revoke on deletion).
    ...(code ? { code, redirectUri } : {}),
  };
}

let sdkLoading: Promise<AppleSdk> | undefined;

function loadedSdk(): AppleSdk | undefined {
  return (window as Window & { AppleID?: AppleSdk }).AppleID;
}

/** Starts loading Apple's SDK before the button is pressed. */
export function preloadAppleSdk(): void {
  loadAppleSdk().catch(() => {
    // Offline or blocked: the tap tries again and says so if it fails.
  });
}

function loadAppleSdk(): Promise<AppleSdk> {
  const existing = loadedSdk();
  if (existing) return Promise.resolve(existing);
  // Two quick taps load the script once.
  sdkLoading ??= new Promise<AppleSdk>((resolve, reject) => {
    const script = document.createElement('script');
    script.src = APPLE_SDK_URL;
    script.async = true;
    script.onload = () => {
      const loaded = (window as Window & { AppleID?: AppleSdk }).AppleID;
      if (loaded) resolve(loaded);
      else reject(new Error('Apple SDK did not initialise'));
    };
    script.onerror = () => {
      reject(new Error('Apple SDK could not be loaded'));
    };
    document.head.appendChild(script);
  }).catch((error: unknown) => {
    // A failed load (offline) may be retried with the next tap.
    sdkLoading = undefined;
    throw error;
  });
  return sdkLoading;
}

/**
 * Whether a sign-in ended because the person closed it. That is a choice,
 * not a failure, and the page says nothing. Apple's popup rejects with
 * `{ error: 'popup_closed_by_user' }` (or `user_cancelled_authorize`); the
 * native sheets (Apple and Google) reject with the plugin's USER_CANCELLED.
 */
export function isSignInCancelled(error: unknown): boolean {
  if (typeof error !== 'object' || error === null) return false;
  const { code, error: kind } = error as { code?: unknown; error?: unknown };
  return code === 'USER_CANCELLED' || kind === 'popup_closed_by_user' || kind === 'user_cancelled_authorize';
}
